settings.liquid:
{%- if template.name == 'article' and article -%}
<script type="application/ld+json">
{
  "@context": "https://schema.org",
  "@type": "BlogPosting",
  "mainEntityOfPage": {
    "@type": "WebPage",
    "@id": {{ article.url | absolute_url | json }}
  },
  "headline": {{ article.title | strip_html | json }},
  "description": {{ article.excerpt_or_content | strip_html | truncate: 160 | json }},
  "datePublished": {{ article.published_at | date: "%Y-%m-%d" | json }},
  "dateModified": {{ article.updated_at | date: "%Y-%m-%d" | json }},
  "author": {
    "@type": "Organization",
    "name": {{ shop.name | json }}
  },
  "publisher": {
    "@type": "Organization",
    "name": {{ shop.name | json }}
    {%- if settings.logo != blank -%},
    "logo": {
      "@type": "ImageObject",
      "url": {{ settings.logo | image_url: width: 600 | absolute_url | json }}
    }
    {%- endif -%}
  }
  {%- if article.image -%},
  "image": [
    {{ article.image | image_url: width: 1200 | absolute_url | json }}
  ]
  {%- endif -%}
}
</script>
{%- endif -%}
